  /** The period during which some deployable was active in a runtime. */
  deployment?: Occurrence_Deployment | Computed<Occurrence_Deployment>;
  /** Provides information about the analysis status of a discovered resource. */
  discovery?: Occurrence_Discovery | Computed<Occurrence_Discovery>;
  /** Deprecated. Prefer to use a regular Occurrence, and populate the Envelope at the top level of the Occurrence. */
  dsseAttestation?: Occurrence_DsseAttestation | Computed<Occurrence_DsseAttestation>;
  /** MUST match https://github.com/secure-systems-lab/dsse/blob/master/envelope.proto. An authenticated message of arbitrary type. */
